use std::{io::{Read,Write},net::TcpListener,sync::{Arc,Mutex},thread,time::Duration};
use serde_json::{Value,json};
use zwen_core::{completion::{Message,Role,FinishReason},paper::{Source,Metadata,ReadingOptions},provider::{ProviderConfig,ApiKey}};
use zwen_transport::{paper_agent,Error};
use tokio::sync::watch;
fn doc()->zwen_core::paper::PreparedReading{Source{meta:Metadata{id:"0123456789abcdef0123456789abcdef".into(),name:"long.pdf".into(),page_count:2,readable_pages:2},pages:vec!["INTRO ".repeat(60000),"METHOD precise synthetic evidence".into()]}.prepare(&ReadingOptions{read_images:false,..Default::default()},"解释方法证据").unwrap()}
fn sse(delta:Value,reason:Option<&str>)->String{format!("data: {}\n\n",json!({"choices":[{"index":0,"delta":delta,"finish_reason":reason}]}))}
fn response(call:bool,id:usize)->String{if call{let a=sse(json!({"tool_calls":[{"index":0,"id":format!("call_{id}"),"type":"function","function":{"name":"read_paper_page","arguments":"{\"pa"}}]}),None);a+&sse(json!({"tool_calls":[{"index":0,"function":{"arguments":"ge\":2}"}}]}),Some("tool_calls"))+"data: [DONE]\n\n"}else{sse(json!({"content":"# Final report\nMarkdown } works"}),Some("stop"))+"data: [DONE]\n\n"}}
fn service(replies:Vec<String>)->(ProviderConfig,Arc<Mutex<Vec<Value>>>,thread::JoinHandle<()>){let server=TcpListener::bind("127.0.0.1:0").unwrap();let port=server.local_addr().unwrap().port();server.set_nonblocking(true).unwrap();let seen=Arc::new(Mutex::new(Vec::new()));let copy=seen.clone();let t=thread::spawn(move||{for response in replies{let deadline=std::time::Instant::now()+Duration::from_secs(5);let mut socket=loop{match server.accept(){Ok((s,_))=>break s,Err(_)if std::time::Instant::now()<deadline=>thread::sleep(Duration::from_millis(5)),Err(_)=>return}};socket.set_read_timeout(Some(Duration::from_secs(2))).unwrap();let mut bytes=Vec::new();let mut buf=[0;4096];loop{let n=socket.read(&mut buf).unwrap();if n==0{return;}bytes.extend_from_slice(&buf[..n]);if let Some(i)=bytes.windows(4).position(|x|x==b"\r\n\r\n"){let h=String::from_utf8_lossy(&bytes[..i]);let size:usize=h.lines().find_map(|l|l.to_ascii_lowercase().strip_prefix("content-length:").map(|v|v.trim().parse().unwrap())).unwrap();if bytes.len()>=i+4+size{copy.lock().unwrap().push(serde_json::from_slice(&bytes[i+4..i+4+size]).unwrap());break;}}}let header=format!("HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",response.len());let _=socket.write_all(header.as_bytes());let _=socket.write_all(response.as_bytes());}});(ProviderConfig::new(&format!("http://127.0.0.1:{port}/v1"),"fixture","KEY").unwrap(),seen,t)}
fn runtime()->tokio::runtime::Runtime{tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap()}
#[test]fn long_reading_retrieves_only_bound_material_and_generates_markdown(){runtime().block_on(async{let(c,seen,t)=service(vec![response(true,1),response(false,2)]);let p=doc();let messages=vec![Message{role:Role::User,content:p.prompt,images:vec![]}];let(_tx,rx)=watch::channel(false);let mut out=String::new();let r=paper_agent::read(&zwen_transport::client().unwrap(),&c,&ApiKey::new("fake").unwrap(),&messages,p.document.unwrap(),rx,|s|{out.push_str(s);Ok(())}).await;assert_eq!(r,Ok(FinishReason::Stop));assert!(out.contains("完整返回文字的页：2"));assert!(out.contains("未通过读页工具读取的页：1"));assert!(out.contains("Markdown } works"));t.join().unwrap();let bodies=seen.lock().unwrap();assert_eq!(bodies.len(),2);assert_eq!(bodies[0]["tools"].as_array().unwrap().len(),2);assert!(!bodies[0].to_string().contains(&"INTRO ".repeat(30)));assert_eq!(bodies[1]["messages"][2]["role"],"tool");assert!(bodies[1]["messages"][2]["content"].as_str().unwrap().contains("precise synthetic evidence"));});}
#[test]fn refusing_tools_cannot_fake_a_completed_long_reading(){runtime().block_on(async{let(c,_,t)=service(vec![response(false,0)]);let p=doc();let(_tx,rx)=watch::channel(false);let mut out=String::new();let r=paper_agent::read(&zwen_transport::client().unwrap(),&c,&ApiKey::new("fake").unwrap(),&[Message{role:Role::User,content:p.prompt,images:vec![]}],p.document.unwrap(),rx,|s|{out.push_str(s);Ok(())}).await;assert_eq!(r,Err(Error::DocumentTools));assert!(!out.contains("Final report"));t.join().unwrap();});}
#[test]fn sixth_request_forces_a_final_answer_and_precancel_never_sends(){runtime().block_on(async{let(c,seen,t)=service((0..6).map(|n|response(n<5,n)).collect());let p=doc();let(_tx,rx)=watch::channel(false);assert_eq!(paper_agent::read(&zwen_transport::client().unwrap(),&c,&ApiKey::new("fake").unwrap(),&[Message{role:Role::User,content:p.prompt,images:vec![]}],p.document.unwrap(),rx,|_|Ok(())).await,Ok(FinishReason::Stop));t.join().unwrap();assert_eq!(seen.lock().unwrap().last().unwrap()["tool_choice"],"none");let p=doc();let(_tx,rx)=watch::channel(true);let r=paper_agent::read(&zwen_transport::client().unwrap(),&c,&ApiKey::new("fake").unwrap(),&[],p.document.unwrap(),rx,|_|Ok(())).await;assert_eq!(r,Err(Error::Cancelled));});}
#[test]fn partial_final_text_and_coverage_survive_disconnect(){runtime().block_on(async{let broken=sse(json!({"content":"PARTIAL_FINAL_TEXT"}),None);let(c,_,t)=service(vec![response(true,1),broken]);let p=doc();let(_tx,rx)=watch::channel(false);let mut out=String::new();let r=paper_agent::read(&zwen_transport::client().unwrap(),&c,&ApiKey::new("fake").unwrap(),&[Message{role:Role::User,content:p.prompt,images:vec![]}],p.document.unwrap(),rx,|s|{out.push_str(s);Ok(())}).await;assert_eq!(r,Err(Error::Protocol));assert!(out.contains("PARTIAL_FINAL_TEXT"));assert!(out.contains("完整返回文字的页：2"));t.join().unwrap();});}
#[test]fn cancellation_after_final_text_keeps_text_and_coverage(){runtime().block_on(async{let(c,_,t)=service(vec![response(true,1),response(false,2)]);let p=doc();let(tx,rx)=watch::channel(false);let mut out=String::new();let r=paper_agent::read(&zwen_transport::client().unwrap(),&c,&ApiKey::new("fake").unwrap(),&[Message{role:Role::User,content:p.prompt,images:vec![]}],p.document.unwrap(),rx,|s|{out.push_str(s);if s.contains("Final report"){let _=tx.send(true);}Ok(())}).await;assert_eq!(r,Err(Error::Cancelled));assert!(out.contains("Final report"));assert!(out.contains("完整返回文字的页：2"));t.join().unwrap();});}
